-- Market reference M2 (ADR 0023): the SQL functions against the same shared vectors the TypeScript reads.
-- Part 1 parse vectors: strict JSON, SGS daily and Copom detail results and refusal codes. Part 0
-- vectors: canonical v2 text and digest, its refusal codes, data-base limits, eligibility at the limit
-- and the communiqué record fingerprint. The vectors were generated by an independent implementation;
-- any difference fails the database job. Runs from the repository root; nothing is written.
begin;
\set parse_vectors `cat packages/market-reference/vectors/market-m2-part1-parse.json`
\set part0_vectors `cat packages/market-reference/vectors/market-m2-part0.json`
create temporary table vectors(name text primary key,doc jsonb);
insert into vectors values('parse',:'parse_vectors'),('part0',:'part0_vectors');

do $$ declare c jsonb;bytes bytea;got jsonb;err text;failures text[]:='{}';n int:=0;begin
 for c in select jsonb_array_elements(doc->'cases') from vectors where name='parse' loop
  n:=n+1;got:=null;err:=null;
  bytes:=case when (c->>'contentBase64')::boolean then decode(c->>'content','base64') else convert_to(c->>'content','UTF8') end;
  begin
   if c->>'kind'='sgs' then
    select jsonb_build_object('observations',coalesce(jsonb_agg(jsonb_build_object('period',to_char(p.period,'YYYY-MM-DD'),'value',p.value) order by p.period),'[]'))
    into got from private.market_parse_sgs_daily_v1(bytes,(c#>>'{window,start}')::date,(c#>>'{window,end}')::date,(c->>'dataBase')::date) p;
   else
    select jsonb_build_object('referenceDate',to_char(d.reference_date,'YYYY-MM-DD'),'decision',d.decision,'targetPct',d.target_pct,
     'seriesChangeDate',to_char(d.series_change_date,'YYYY-MM-DD'),'regulatoryEffectiveFrom',to_char(d.regulatory_effective_from,'YYYY-MM-DD'))
    into got from private.market_parse_copom_detail_v1(bytes,(c->>'meeting')::int) d;
   end if;
  exception when others then err:=sqlerrm;
  end;
  if (case when c->'expect' ? 'error' then err is distinct from c#>>'{expect,error}' else err is not null or got is distinct from c->'expect' end)
  then failures:=failures||(c->>'name'||': '||coalesce(err,got::text));end if;
 end loop;
 if n<50 then raise exception 'parse vectors not loaded (%)',n;end if;
 if cardinality(failures)>0 then raise exception 'SQL parse differs from the shared vectors: %',array_to_string(failures,' | ');end if;
end $$;

do $$ declare c jsonb;v jsonb;txt text;err text;failures text[]:='{}';lim timestamptz;begin
 select doc into v from vectors where name='part0';
 if jsonb_array_length(v->'canonicalV2')=0 or jsonb_array_length(v->'canonicalV2Refusals')=0 then raise exception 'part 0 vectors not loaded';end if;
 for c in select jsonb_array_elements(v->'canonicalV2') loop
  txt:=null;err:=null;
  begin txt:=private.market_canonical_v2_text_v1(c->'input');exception when others then err:=sqlerrm;end;
  if err is not null or txt is distinct from c->>'canonical' or encode(extensions.digest(convert_to(txt,'UTF8'),'sha256'),'hex') is distinct from c->>'sha256'
  then failures:=failures||('canonical '||(c->>'name')||': '||coalesce(err,'text or digest differs'));end if;
 end loop;
 for c in select jsonb_array_elements(v->'canonicalV2Refusals') loop
  err:=null;
  begin perform private.market_canonical_v2_text_v1(c->'input');exception when others then err:=sqlerrm;end;
  if err is distinct from c->>'error' then failures:=failures||('refusal '||(c->>'name')||': '||coalesce(err,'accepted'));end if;
 end loop;
 for c in select jsonb_array_elements(v->'dataBaseLimits') loop
  if private.market_data_base_limit_v1((c->>'dataBase')::date) is distinct from (c->>'limit')::timestamptz
  then failures:=failures||('limit '||(c->>'dataBase'));end if;
 end loop;
 for c in select jsonb_array_elements(v->'eligibility') loop
  lim:=private.market_data_base_limit_v1((c->>'dataBase')::date);
  if ((c->>'acquiredAt')::timestamptz<lim) is distinct from (c->>'eligible')::boolean then failures:=failures||('eligibility '||(c->>'acquiredAt'));end if;
 end loop;
 for c in select jsonb_array_elements(v->'communiqueRecords') loop
  if private.market_communique_record_sha256_v1((c#>>'{record,nro_reuniao}')::int,c#>>'{record,dataReferencia}',c#>>'{record,titulo}',c#>>'{record,textoComunicado}')
   is distinct from c->>'sha256' then failures:=failures||('record '||(c#>>'{record,nro_reuniao}'));end if;
 end loop;
 if (select normalization_sha256 from private.market_normalizations where id='bcb-sgs-432') is distinct from v->>'seriesContractSha256'
 then failures:=failures||'series contract digest'::text;end if;
 if cardinality(failures)>0 then raise exception 'SQL differs from the part 0 vectors: %',array_to_string(failures,' | ');end if;
end $$;
rollback;
